INSERT INTO `categories` VALUES (1,'Bedroom Interior Design Projects','bedroom-interior-design-projects-bangladesh','project','Explore Bedroom Interior Design Projects in Bangladesh crafted by Triangle Interior Design\'s award-winning architects and designers.',NULL,NULL,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(2,'Master Bedroom Interior Design Projects','master-bedroom-interior-design-projects-bangladesh','project','Explore Master Bedroom Interior Design Projects in Bangladesh crafted by Triangle Interior Design\'s award-winning architects and designers.',NULL,NULL,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(3,'Kids Bedroom Interior Design Projects','kids-bedroom-interior-design-projects-bangladesh','project','Explore Kids Bedroom Interior Design Projects in Bangladesh crafted by Triangle Interior Design\'s award-winning architects and designers.',NULL,NULL,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(4,'Guest Bedroom Interior Design Projects','guest-bedroom-interior-design-projects-bangladesh','project','Explore Guest Bedroom Interior Design Projects in Bangladesh crafted by Triangle Interior Design\'s award-winning architects and designers.',NULL,NULL,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(5,'Living Room Interior Design Projects','living-room-interior-design-projects-bangladesh','project','Explore Living Room Interior Design Projects in Bangladesh crafted by Triangle Interior Design\'s award-winning architects and designers.',NULL,NULL,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(6,'Dining Room Interior Design Projects','dining-room-interior-design-projects-bangladesh','project','Explore Dining Room Interior Design Projects in Bangladesh crafted by Triangle Interior Design\'s award-winning architects and designers.',NULL,NULL,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(7,'Kitchen Interior Design Projects','kitchen-interior-design-projects-bangladesh','project','Explore Kitchen Interior Design Projects in Bangladesh crafted by Triangle Interior Design\'s award-winning architects and designers.',NULL,NULL,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(8,'Modular Kitchen Design Projects','modular-kitchen-projects-bangladesh','project','Explore Modular Kitchen Design Projects in Bangladesh crafted by Triangle Interior Design\'s award-winning architects and designers.',NULL,NULL,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(9,'Open Kitchen Design Projects','open-kitchen-design-projects-bangladesh','project','Explore Open Kitchen Design Projects in Bangladesh crafted by Triangle Interior Design\'s award-winning architects and designers.',NULL,NULL,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(10,'Common Area Interior Design Projects','common-area-interior-design-projects-bangladesh','project','Explore Common Area Interior Design Projects in Bangladesh crafted by Triangle Interior Design\'s award-winning architects and designers.',NULL,NULL,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(11,'Cabinet Design Projects','cabinet-design-projects-bangladesh','project','Explore Cabinet Design Projects in Bangladesh crafted by Triangle Interior Design\'s award-winning architects and designers.',NULL,NULL,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(12,'Luxury Interior Design Projects','luxury-interior-design-projects','project','Explore Luxury Interior Design Projects in Bangladesh crafted by Triangle Interior Design\'s award-winning architects and designers.',NULL,NULL,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(13,'Modern Interior Design Projects','modern-interior-design-projects','project','Explore Modern Interior Design Projects in Bangladesh crafted by Triangle Interior Design\'s award-winning architects and designers.',NULL,NULL,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(14,'Closet Design Projects','closet-design-projects-bangladesh','project','Explore Closet Design Projects in Bangladesh crafted by Triangle Interior Design\'s award-winning architects and designers.',NULL,NULL,'2026-10-13 00:00:22','2026-10-13 00:00:22');
