INSERT INTO `services` VALUES (1,'HomeInterior Designin Dhaka, Bangladesh','home-interior-design','fa-house-chimney','Bangladesh\'s Most Trusted Home Interior Company\n\nFrom the living room to the last corner of your bedroom, we plan, design, and execute every space in your home...','Bangladesh\'s Most Trusted Home Interior Company\n\nFrom the living room to the last corner of your bedroom, we plan, design, and execute every space in your home with care. No generic design. No shortcuts.\n\nComplete Interior Solutions\n\nEvery room designed, built, and installed by our interior team — bedrooms, living rooms, kitchens, bathrooms, and common spaces\n\nIn-House Manufacturing\n\nAll furniture and cabinetry built at our own factory in West Badda with full quality control','[\"Tailored 100% to your lifestyle and space ergonomics\",\"Premium grade imported boards, hardware & finishes\",\"Direct in-house manufacturing in West Badda factory\",\"Dedicated project manager and on-time handover warranty\",\"Transparent itemized BOQ with zero hidden costs\"]','[{\"step\":\"01\",\"title\":\"Initial Consultation\",\"desc\":\"In-depth discussion of your lifestyle, aesthetic taste, functional needs, and budget.\"},{\"step\":\"02\",\"title\":\"Space Planning & 2D Layout\",\"desc\":\"Comprehensive architectural measurements and ergonomic space utilization.\"},{\"step\":\"03\",\"title\":\"Photorealistic 3D Renderings\",\"desc\":\"Full 360-degree visualization of materials, textures, lighting, and finishes.\"},{\"step\":\"04\",\"title\":\"Itemized BOQ & Material Selection\",\"desc\":\"100% transparent cost estimation without any hidden expenses.\"},{\"step\":\"05\",\"title\":\"In-House Factory Manufacturing\",\"desc\":\"Precision joinery crafted at our West Badda workshop using German hardware.\"},{\"step\":\"06\",\"title\":\"On-Site Execution & Quality Control\",\"desc\":\"Supervised civil, electrical, plumbing, false ceiling, and painting work.\"},{\"step\":\"07\",\"title\":\"Styling & Detailing\",\"desc\":\"Curated illumination, soft furnishings, decor accents, and deep sanitization.\"},{\"step\":\"08\",\"title\":\"Formal Handover & Warranty\",\"desc\":\"Punctual handover with comprehensive warranty and after-sales support.\"}]','images/dit-studio-logo.webp','[\"images\\/dit-studio-logo.webp\",\"images\\/dit-studio-logo.webp\",\"images\\/dit.png\",\"images\\/photo-1.avif\",\"images\\/photo-2.avif\",\"images\\/interior-designer-reviewing.jpg\"]',1,1,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(2,'Landscape Designin Dhaka, Bangladesh','landscape-design','fa-tree','Bangladesh\'s Trusted Landscape Design Company\n\nWe design outdoor spaces that feel alive. Green, peaceful, and made for the way you actually live, whether it is...','Bangladesh\'s Trusted Landscape Design Company\n\nWe design outdoor spaces that feel alive. Green, peaceful, and made for the way you actually live, whether it is a rooftop garden, a villa yard, or a commercial compound in Dhaka.\n\nGet a free interior design consultation and receive your customized quotation within 24 hours.\n\n🔒 Your information is 100% secure.\n\nGreenery that improves your outdoor air quality and brings natural calm to your home.\n\nWe plan every corner of your outdoor area so nothing goes to waste — small or large.','[\"Tailored 100% to your lifestyle and space ergonomics\",\"Premium grade imported boards, hardware & finishes\",\"Direct in-house manufacturing in West Badda factory\",\"Dedicated project manager and on-time handover warranty\",\"Transparent itemized BOQ with zero hidden costs\"]','[{\"step\":\"01\",\"title\":\"Initial Consultation\",\"desc\":\"In-depth discussion of your lifestyle, aesthetic taste, functional needs, and budget.\"},{\"step\":\"02\",\"title\":\"Space Planning & 2D Layout\",\"desc\":\"Comprehensive architectural measurements and ergonomic space utilization.\"},{\"step\":\"03\",\"title\":\"Photorealistic 3D Renderings\",\"desc\":\"Full 360-degree visualization of materials, textures, lighting, and finishes.\"},{\"step\":\"04\",\"title\":\"Itemized BOQ & Material Selection\",\"desc\":\"100% transparent cost estimation without any hidden expenses.\"},{\"step\":\"05\",\"title\":\"In-House Factory Manufacturing\",\"desc\":\"Precision joinery crafted at our West Badda workshop using German hardware.\"},{\"step\":\"06\",\"title\":\"On-Site Execution & Quality Control\",\"desc\":\"Supervised civil, electrical, plumbing, false ceiling, and painting work.\"},{\"step\":\"07\",\"title\":\"Styling & Detailing\",\"desc\":\"Curated illumination, soft furnishings, decor accents, and deep sanitization.\"},{\"step\":\"08\",\"title\":\"Formal Handover & Warranty\",\"desc\":\"Punctual handover with comprehensive warranty and after-sales support.\"}]','images/dit-studio-logo.webp','[\"images\\/dit-studio-logo.webp\",\"images\\/dit-studio-logo.webp\",\"images\\/dit.png\",\"images\\/landscape-design-1.webp\",\"images\\/landscape-design-4.webp\",\"images\\/landscape-design-5.webp\"]',2,1,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(3,'Bathroom Designin Bangladesh','bathroom-design','fa-bath','Dhaka\'s Trusted Bathroom Designers\n\nMost bathrooms in Bangladesh flats are treated as an afterthought – basic tiles, standard fittings, and little consideration...','Dhaka\'s Trusted Bathroom Designers\n\nMost bathrooms in Bangladesh flats are treated as an afterthought – basic tiles, standard fittings, and little consideration for how the space actually works day to day. At Triangle Interior Design, our interior designers approach your bathroom with the same precision and care we give to every room in your home.\n\nGet a free interior design consultation and receive your customized quotation within 24 hours.\n\n🔒 Your information is 100% secure.\n\nEvery material we use is tested for Bangladesh\'s humid climate.\n\nVanities, niches, and shelving planned to keep your bathroom clutter-free.','[\"Tailored 100% to your lifestyle and space ergonomics\",\"Premium grade imported boards, hardware & finishes\",\"Direct in-house manufacturing in West Badda factory\",\"Dedicated project manager and on-time handover warranty\",\"Transparent itemized BOQ with zero hidden costs\"]','[{\"step\":\"01\",\"title\":\"Initial Consultation\",\"desc\":\"In-depth discussion of your lifestyle, aesthetic taste, functional needs, and budget.\"},{\"step\":\"02\",\"title\":\"Space Planning & 2D Layout\",\"desc\":\"Comprehensive architectural measurements and ergonomic space utilization.\"},{\"step\":\"03\",\"title\":\"Photorealistic 3D Renderings\",\"desc\":\"Full 360-degree visualization of materials, textures, lighting, and finishes.\"},{\"step\":\"04\",\"title\":\"Itemized BOQ & Material Selection\",\"desc\":\"100% transparent cost estimation without any hidden expenses.\"},{\"step\":\"05\",\"title\":\"In-House Factory Manufacturing\",\"desc\":\"Precision joinery crafted at our West Badda workshop using German hardware.\"},{\"step\":\"06\",\"title\":\"On-Site Execution & Quality Control\",\"desc\":\"Supervised civil, electrical, plumbing, false ceiling, and painting work.\"},{\"step\":\"07\",\"title\":\"Styling & Detailing\",\"desc\":\"Curated illumination, soft furnishings, decor accents, and deep sanitization.\"},{\"step\":\"08\",\"title\":\"Formal Handover & Warranty\",\"desc\":\"Punctual handover with comprehensive warranty and after-sales support.\"}]','images/dit-studio-logo.webp','[\"images\\/dit-studio-logo.webp\",\"images\\/dit-studio-logo.webp\",\"images\\/dit.png\",\"images\\/bathroom-design-2-scaled.webp\",\"images\\/bathroom-design-service.webp\",\"images\\/bathroom-solutions-scaled.webp\"]',3,1,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(4,'Traditional Kitchen Designin Dhaka, Bangladesh','traditional-kitchen-design','fa-fire-burner','Dhaka\'s Trusted Kitchen Designers\n\nBangladeshi cooking is intense. The deep frying, the bhuna, the slow-cooked curries — your kitchen has to handle it all witho...','Dhaka\'s Trusted Kitchen Designers\n\nBangladeshi cooking is intense. The deep frying, the bhuna, the slow-cooked curries — your kitchen has to handle it all without wearing down. Most kitchens in Dhaka flats are not designed for this reality. At Triangle Interior Design, our interior designers create traditional enclosed kitchens that are purpose-built for the way you actually cook.\n\nGet a free interior design consultation and receive your customized quotation within 24 hours.\n\n🔒 Your information is 100% secure.\n\nSmart layouts that give you room to move, even in a small kitchen.\n\nWe use quality materials that handle daily cooking heat, oil, and moisture without any problem.','[\"Tailored 100% to your lifestyle and space ergonomics\",\"Premium grade imported boards, hardware & finishes\",\"Direct in-house manufacturing in West Badda factory\",\"Dedicated project manager and on-time handover warranty\",\"Transparent itemized BOQ with zero hidden costs\"]','[{\"step\":\"01\",\"title\":\"Initial Consultation\",\"desc\":\"In-depth discussion of your lifestyle, aesthetic taste, functional needs, and budget.\"},{\"step\":\"02\",\"title\":\"Space Planning & 2D Layout\",\"desc\":\"Comprehensive architectural measurements and ergonomic space utilization.\"},{\"step\":\"03\",\"title\":\"Photorealistic 3D Renderings\",\"desc\":\"Full 360-degree visualization of materials, textures, lighting, and finishes.\"},{\"step\":\"04\",\"title\":\"Itemized BOQ & Material Selection\",\"desc\":\"100% transparent cost estimation without any hidden expenses.\"},{\"step\":\"05\",\"title\":\"In-House Factory Manufacturing\",\"desc\":\"Precision joinery crafted at our West Badda workshop using German hardware.\"},{\"step\":\"06\",\"title\":\"On-Site Execution & Quality Control\",\"desc\":\"Supervised civil, electrical, plumbing, false ceiling, and painting work.\"},{\"step\":\"07\",\"title\":\"Styling & Detailing\",\"desc\":\"Curated illumination, soft furnishings, decor accents, and deep sanitization.\"},{\"step\":\"08\",\"title\":\"Formal Handover & Warranty\",\"desc\":\"Punctual handover with comprehensive warranty and after-sales support.\"}]','images/dit-studio-logo.webp','[\"images\\/dit-studio-logo.webp\",\"images\\/dit-studio-logo.webp\",\"images\\/dit.png\",\"images\\/modular-kitchen-design-service.webp\",\"images\\/modern-kitchen-design-2.webp\",\"images\\/modern-kitchen-design-8-scaled.webp\"]',4,1,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(5,'Modular Kitchen Designin Dhaka, Bangladesh','modular-kitchen-design','fa-kitchen-set','We design modular kitchens that fit your space, your cooking style, and your budget built right here in Bangladesh with quality materials and honest craftsmansh...','We design modular kitchens that fit your space, your cooking style, and your budget built right here in Bangladesh with quality materials and honest craftsmanship.\n\nGet a free interior design consultation and receive your customized quotation within 24 hours.\n\n🔒 Your information is 100% secure.\n\nEvery drawer, cabinet, and shelf is planned so nothing gets wasted. No more cluttered countertops or lost corners.\n\nSmooth surfaces, sealed edges, and the right material choices make your modular kitchen easy to maintain every day.\n\nOur kitchen layouts are designed around how we cook here from bhapá dishes to deep frying not just copied from foreign catalogues.','[\"Tailored 100% to your lifestyle and space ergonomics\",\"Premium grade imported boards, hardware & finishes\",\"Direct in-house manufacturing in West Badda factory\",\"Dedicated project manager and on-time handover warranty\",\"Transparent itemized BOQ with zero hidden costs\"]','[{\"step\":\"01\",\"title\":\"Initial Consultation\",\"desc\":\"In-depth discussion of your lifestyle, aesthetic taste, functional needs, and budget.\"},{\"step\":\"02\",\"title\":\"Space Planning & 2D Layout\",\"desc\":\"Comprehensive architectural measurements and ergonomic space utilization.\"},{\"step\":\"03\",\"title\":\"Photorealistic 3D Renderings\",\"desc\":\"Full 360-degree visualization of materials, textures, lighting, and finishes.\"},{\"step\":\"04\",\"title\":\"Itemized BOQ & Material Selection\",\"desc\":\"100% transparent cost estimation without any hidden expenses.\"},{\"step\":\"05\",\"title\":\"In-House Factory Manufacturing\",\"desc\":\"Precision joinery crafted at our West Badda workshop using German hardware.\"},{\"step\":\"06\",\"title\":\"On-Site Execution & Quality Control\",\"desc\":\"Supervised civil, electrical, plumbing, false ceiling, and painting work.\"},{\"step\":\"07\",\"title\":\"Styling & Detailing\",\"desc\":\"Curated illumination, soft furnishings, decor accents, and deep sanitization.\"},{\"step\":\"08\",\"title\":\"Formal Handover & Warranty\",\"desc\":\"Punctual handover with comprehensive warranty and after-sales support.\"}]','images/dit-studio-logo.webp','[\"images\\/dit-studio-logo.webp\",\"images\\/dit-studio-logo.webp\",\"images\\/dit.png\",\"images\\/modular-kitchen-design-2.webp\",\"images\\/modular-kitchen-design-1-2.webp\",\"images\\/modular-kitchen-design-2-3.webp\"]',5,1,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(6,'Open Kitchen Designin Dhaka, Bangladesh','open-kitchen-design','fa-utensils','Dhaka\'s Most Trusted Kitchen Design Company\n\nWe design open kitchens for real Bangladeshi homes. More space, more light, and a layout that makes daily cooking e...','Dhaka\'s Most Trusted Kitchen Design Company\n\nWe design open kitchens for real Bangladeshi homes. More space, more light, and a layout that makes daily cooking easier and more enjoyable for your whole family.\n\nGet a free interior design consultation and receive your customized quotation within 24 hours.\n\n🔒 Your information is 100% secure.\n\nAn open kitchen lets natural light come in from the living and dining area all day long.\n\nGood air movement means cooking smells do not stay inside your home for long.','[\"Tailored 100% to your lifestyle and space ergonomics\",\"Premium grade imported boards, hardware & finishes\",\"Direct in-house manufacturing in West Badda factory\",\"Dedicated project manager and on-time handover warranty\",\"Transparent itemized BOQ with zero hidden costs\"]','[{\"step\":\"01\",\"title\":\"Initial Consultation\",\"desc\":\"In-depth discussion of your lifestyle, aesthetic taste, functional needs, and budget.\"},{\"step\":\"02\",\"title\":\"Space Planning & 2D Layout\",\"desc\":\"Comprehensive architectural measurements and ergonomic space utilization.\"},{\"step\":\"03\",\"title\":\"Photorealistic 3D Renderings\",\"desc\":\"Full 360-degree visualization of materials, textures, lighting, and finishes.\"},{\"step\":\"04\",\"title\":\"Itemized BOQ & Material Selection\",\"desc\":\"100% transparent cost estimation without any hidden expenses.\"},{\"step\":\"05\",\"title\":\"In-House Factory Manufacturing\",\"desc\":\"Precision joinery crafted at our West Badda workshop using German hardware.\"},{\"step\":\"06\",\"title\":\"On-Site Execution & Quality Control\",\"desc\":\"Supervised civil, electrical, plumbing, false ceiling, and painting work.\"},{\"step\":\"07\",\"title\":\"Styling & Detailing\",\"desc\":\"Curated illumination, soft furnishings, decor accents, and deep sanitization.\"},{\"step\":\"08\",\"title\":\"Formal Handover & Warranty\",\"desc\":\"Punctual handover with comprehensive warranty and after-sales support.\"}]','images/dit-studio-logo.webp','[\"images\\/dit-studio-logo.webp\",\"images\\/dit-studio-logo.webp\",\"images\\/dit.png\",\"images\\/modern-kitchen-design-7-1.webp\",\"images\\/open-kitchen-design-in-bangladesh.webp\",\"images\\/modular-kitchen-design-service.webp\"]',6,1,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(7,'Living Room Interior Designin Bangladesh','living-room-design','fa-tv','Dhaka\'s Best Living Room Interior Designer\n\nMost living rooms in Dhaka look good in photos but feel uncomfortable to actually sit in. The sofa is too big, the T...','Dhaka\'s Best Living Room Interior Designer\n\nMost living rooms in Dhaka look good in photos but feel uncomfortable to actually sit in. The sofa is too big, the TV unit blocks movement, the lighting is too harsh, or the room just feels disconnected. At Triangle Interior Design, we fix all of that. Our living room interior design is planned around how your family actually lives, the guests who visit, the kids who play on the floor, and the evenings you spend unwinding after a long day.\n\nEvery living room designed by our interior consultants to match your lifestyle, room dimensions, and aesthetic preferences\n\nTV units, accent walls, shelving, and cabinetry built at our own factory with rigorous quality control\n\nInternational-grade laminates, veneers, engineered wood, and branded hardware selected for Dhaka’s climate\n\nGet a free interior design consultation and receive your customized quotation within 24 hours.','[\"Tailored 100% to your lifestyle and space ergonomics\",\"Premium grade imported boards, hardware & finishes\",\"Direct in-house manufacturing in West Badda factory\",\"Dedicated project manager and on-time handover warranty\",\"Transparent itemized BOQ with zero hidden costs\"]','[{\"step\":\"01\",\"title\":\"Initial Consultation\",\"desc\":\"In-depth discussion of your lifestyle, aesthetic taste, functional needs, and budget.\"},{\"step\":\"02\",\"title\":\"Space Planning & 2D Layout\",\"desc\":\"Comprehensive architectural measurements and ergonomic space utilization.\"},{\"step\":\"03\",\"title\":\"Photorealistic 3D Renderings\",\"desc\":\"Full 360-degree visualization of materials, textures, lighting, and finishes.\"},{\"step\":\"04\",\"title\":\"Itemized BOQ & Material Selection\",\"desc\":\"100% transparent cost estimation without any hidden expenses.\"},{\"step\":\"05\",\"title\":\"In-House Factory Manufacturing\",\"desc\":\"Precision joinery crafted at our West Badda workshop using German hardware.\"},{\"step\":\"06\",\"title\":\"On-Site Execution & Quality Control\",\"desc\":\"Supervised civil, electrical, plumbing, false ceiling, and painting work.\"},{\"step\":\"07\",\"title\":\"Styling & Detailing\",\"desc\":\"Curated illumination, soft furnishings, decor accents, and deep sanitization.\"},{\"step\":\"08\",\"title\":\"Formal Handover & Warranty\",\"desc\":\"Punctual handover with comprehensive warranty and after-sales support.\"}]','images/dit-studio-logo.webp','[\"images\\/dit-studio-logo.webp\",\"images\\/dit-studio-logo.webp\",\"images\\/dit.png\",\"images\\/luxury-living-room-design-2-1.webp\",\"images\\/modern-living-room-design-1-2-scaled.webp\",\"images\\/luxury-living-room-design-2-2.webp\"]',7,1,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(8,'Common Space Designin Dhaka, Bangladesh','common-space-design','fa-shapes','Bangladesh\'s Trusted Interior Experts\n\nIn most Dhaka homes, the spaces between rooms are an afterthought – plain corridors, empty foyers, and dining areas that...','Bangladesh\'s Trusted Interior Experts\n\nIn most Dhaka homes, the spaces between rooms are an afterthought – plain corridors, empty foyers, and dining areas that never quite feel finished. At Triangle Interior Design, our interior designers treat every common space as a design opportunity. We create dining areas, foyers, entryways, corridors, and hallways that connect your rooms with purpose and visual continuity.\n\nGet a free interior design consultation and receive your customized quotation within 24 hours.\n\n🔒 Your information is 100% secure.\n\nYour entryway and foyer set the tone for your entire home. We design them to impress.\n\nWe turn overlooked corridors and pass-through areas into purposeful, stylish spaces.','[\"Tailored 100% to your lifestyle and space ergonomics\",\"Premium grade imported boards, hardware & finishes\",\"Direct in-house manufacturing in West Badda factory\",\"Dedicated project manager and on-time handover warranty\",\"Transparent itemized BOQ with zero hidden costs\"]','[{\"step\":\"01\",\"title\":\"Initial Consultation\",\"desc\":\"In-depth discussion of your lifestyle, aesthetic taste, functional needs, and budget.\"},{\"step\":\"02\",\"title\":\"Space Planning & 2D Layout\",\"desc\":\"Comprehensive architectural measurements and ergonomic space utilization.\"},{\"step\":\"03\",\"title\":\"Photorealistic 3D Renderings\",\"desc\":\"Full 360-degree visualization of materials, textures, lighting, and finishes.\"},{\"step\":\"04\",\"title\":\"Itemized BOQ & Material Selection\",\"desc\":\"100% transparent cost estimation without any hidden expenses.\"},{\"step\":\"05\",\"title\":\"In-House Factory Manufacturing\",\"desc\":\"Precision joinery crafted at our West Badda workshop using German hardware.\"},{\"step\":\"06\",\"title\":\"On-Site Execution & Quality Control\",\"desc\":\"Supervised civil, electrical, plumbing, false ceiling, and painting work.\"},{\"step\":\"07\",\"title\":\"Styling & Detailing\",\"desc\":\"Curated illumination, soft furnishings, decor accents, and deep sanitization.\"},{\"step\":\"08\",\"title\":\"Formal Handover & Warranty\",\"desc\":\"Punctual handover with comprehensive warranty and after-sales support.\"}]','images/dit-studio-logo.webp','[\"images\\/dit-studio-logo.webp\",\"images\\/dit-studio-logo.webp\",\"images\\/dit.png\",\"images\\/luxury-common-space-design-1-2.webp\",\"images\\/luxury-common-space-design-5.webp\",\"images\\/luxury-common-space-design-1-4.webp\"]',8,1,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(9,'BedroomInterior Designin Bangladesh','bedroom-design','fa-bed','We turn plain rooms into peaceful retreats. Proper space planning, custom storage, and the right finishing that fits both your lifestyle and budget.\n\nOptimized...','We turn plain rooms into peaceful retreats. Proper space planning, custom storage, and the right finishing that fits both your lifestyle and budget.\n\nOptimized layouts for Dhaka apartments of every size\n\nHandcrafted wardrobes, beds, and storage built at our in-house factory\n\nOne interior team handles design, manufacturing, and installation\n\nGet a free interior design consultation and receive your customized quotation within 24 hours.\n\n🔒 Your information is 100% secure.','[\"Tailored 100% to your lifestyle and space ergonomics\",\"Premium grade imported boards, hardware & finishes\",\"Direct in-house manufacturing in West Badda factory\",\"Dedicated project manager and on-time handover warranty\",\"Transparent itemized BOQ with zero hidden costs\"]','[{\"step\":\"01\",\"title\":\"Initial Consultation\",\"desc\":\"In-depth discussion of your lifestyle, aesthetic taste, functional needs, and budget.\"},{\"step\":\"02\",\"title\":\"Space Planning & 2D Layout\",\"desc\":\"Comprehensive architectural measurements and ergonomic space utilization.\"},{\"step\":\"03\",\"title\":\"Photorealistic 3D Renderings\",\"desc\":\"Full 360-degree visualization of materials, textures, lighting, and finishes.\"},{\"step\":\"04\",\"title\":\"Itemized BOQ & Material Selection\",\"desc\":\"100% transparent cost estimation without any hidden expenses.\"},{\"step\":\"05\",\"title\":\"In-House Factory Manufacturing\",\"desc\":\"Precision joinery crafted at our West Badda workshop using German hardware.\"},{\"step\":\"06\",\"title\":\"On-Site Execution & Quality Control\",\"desc\":\"Supervised civil, electrical, plumbing, false ceiling, and painting work.\"},{\"step\":\"07\",\"title\":\"Styling & Detailing\",\"desc\":\"Curated illumination, soft furnishings, decor accents, and deep sanitization.\"},{\"step\":\"08\",\"title\":\"Formal Handover & Warranty\",\"desc\":\"Punctual handover with comprehensive warranty and after-sales support.\"}]','images/dit-studio-logo.webp','[\"images\\/dit-studio-logo.webp\",\"images\\/dit-studio-logo.webp\",\"images\\/dit.png\",\"images\\/Conceptual-Architecture-Bedroom.jpg\",\"images\\/Ambiance-Engineering-Bedroom.jpg\",\"images\\/photo-3.avif\"]',9,1,'2026-10-13 00:00:22','2026-10-13 00:00:22'),(10,'Custom Furniture Designin Dhaka, Bangladesh','custom-furniture-design','fa-couch','Dhaka\'s Trusted Furniture Makers\n\nEvery home in Dhaka is different. Standard furniture rarely fits the way it should, and it never feels truly yours. At Triangle Stu...','Dhaka\'s Trusted Furniture Makers\n\nEvery home in Dhaka is different. Standard furniture rarely fits the way it should, and it never feels truly yours. At Triangle Interior Design, our interior designers create custom furniture that completes your space. We design and manufacture bespoke pieces from our own factory in East Badda, giving you full control over dimensions, materials, finishes, and aesthetics. From a single wardrobe to a complete home furniture package, every piece we create is built around your interior vision.\n\nEvery piece designed by our interior team to your exact specifications and room measurements\n\nIn-House Manufacturing\n\nBuilt at our own factory with rigorous quality control at every stage\n\nInternational-grade wood, laminates, hardware, and finishes sourced through our exclusive partnerships','[\"Tailored 100% to your lifestyle and space ergonomics\",\"Premium grade imported boards, hardware & finishes\",\"Direct in-house manufacturing in West Badda factory\",\"Dedicated project manager and on-time handover warranty\",\"Transparent itemized BOQ with zero hidden costs\"]','[{\"step\":\"01\",\"title\":\"Initial Consultation\",\"desc\":\"In-depth discussion of your lifestyle, aesthetic taste, functional needs, and budget.\"},{\"step\":\"02\",\"title\":\"Space Planning & 2D Layout\",\"desc\":\"Comprehensive architectural measurements and ergonomic space utilization.\"},{\"step\":\"03\",\"title\":\"Photorealistic 3D Renderings\",\"desc\":\"Full 360-degree visualization of materials, textures, lighting, and finishes.\"},{\"step\":\"04\",\"title\":\"Itemized BOQ & Material Selection\",\"desc\":\"100% transparent cost estimation without any hidden expenses.\"},{\"step\":\"05\",\"title\":\"In-House Factory Manufacturing\",\"desc\":\"Precision joinery crafted at our West Badda workshop using German hardware.\"},{\"step\":\"06\",\"title\":\"On-Site Execution & Quality Control\",\"desc\":\"Supervised civil, electrical, plumbing, false ceiling, and painting work.\"},{\"step\":\"07\",\"title\":\"Styling & Detailing\",\"desc\":\"Curated illumination, soft furnishings, decor accents, and deep sanitization.\"},{\"step\":\"08\",\"title\":\"Formal Handover & Warranty\",\"desc\":\"Punctual handover with comprehensive warranty and after-sales support.\"}]','images/dit-studio-logo.webp','[\"images\\/dit-studio-logo.webp\",\"images\\/dit-studio-logo.webp\",\"images\\/dit.png\",\"images\\/custom-furniture-design-1.webp\",\"images\\/luxury-living-room-design-1.webp\",\"images\\/luxury-living-room-design-5-3.webp\"]',10,1,'2026-10-13 00:00:22','2026-10-13 00:00:22');
