INSERT INTO `testimonials` VALUES (1,'Engr. Mahbubur Rahman','Homeowner, Gulshan 2','Gulshan 2, Dhaka',5,'3,200 sq ft Luxury Apartment','Triangle Interior Design delivered beyond our wildest expectations. Their in-house factory gave them full quality control, and the final handover was done right on the promised schedule. Their attention to lighting, modular kitchen, and custom closets is unmatched in Bangladesh.','images/client1.webp','2026-10-13 00:00:22','2026-10-13 00:00:22'),(2,'Dr. Nusrat Jahan','Homeowner, Uttara Sector 6','Uttara, Dhaka',5,'1,800 sq ft Modern Apartment','Working with Triangle Interior Design was seamless from day one. The 3D render was 100% faithful to the actual completed rooms. Every cabinet fit with millimeter precision and there were zero hidden charges in their BOQ.','images/client2.webp','2026-10-13 00:00:22','2026-10-13 00:00:22'),(3,'Kazi Tanvir Ahmed','Managing Director','Bashundhara R/A, Dhaka',5,'Full Duplex Interior Design','Truly the most professional interior design firm in Dhaka. We loved their 8-step transparent process and weekly site progress reports. Highly recommended to anyone looking for stress-free luxury interiors.','images/client3.webp','2026-10-13 00:00:22','2026-10-13 00:00:22');
